<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../includes/wardrobe.php';$user=require_role('charity');$pdo=db();$charityId=(int)$user['charity_id'];
if(is_post()){verify_csrf();$pledgeId=(int)($_POST['pledge_id']??0);$action=$_POST['action']??'';$allowed=['approve','cancel','receive'];if(!in_array($action,$allowed,true)){http_response_code(400);exit('Invalid action.');}$pdo->beginTransaction();try{$stmt=$pdo->prepare('SELECT dp.* FROM donation_pledges dp JOIN clothing_requests cr ON cr.id=dp.request_id WHERE dp.id=? AND cr.charity_id=? FOR UPDATE');$stmt->execute([$pledgeId,$charityId]);$pledge=$stmt->fetch();if(!$pledge)throw new RuntimeException('Pledge not found.');if($action==='approve'&&$pledge['status']!=='pending')throw new RuntimeException('Only pending pledges can be approved.');if($action==='cancel'&&!in_array($pledge['status'],['pending','approved','scheduled'],true))throw new RuntimeException('This pledge can no longer be cancelled.');if($action==='receive'){
 if(!in_array($pledge['status'],['approved','scheduled'],true))throw new RuntimeException('Approve a pledge before marking it received.');$items=$pdo->prepare('SELECT di.request_requirement_id,di.quantity,rr.quantity_needed FROM donation_items di JOIN request_requirements rr ON rr.id=di.request_requirement_id WHERE di.pledge_id=? FOR UPDATE');$items->execute([$pledgeId]);foreach($items->fetchAll() as $item){$received=$pdo->prepare('SELECT COALESCE(SUM(di.quantity),0) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id WHERE di.request_requirement_id=? AND dp.status="received"');$received->execute([$item['request_requirement_id']]);if((int)$received->fetchColumn()+(int)$item['quantity']>(int)$item['quantity_needed'])throw new RuntimeException('This pledge would exceed the remaining quantity. Ask the donor to adjust it or cancel it.');}}
 $newStatus=$action==='approve'?'approved':($action==='receive'?'received':'cancelled');$pdo->prepare('UPDATE donation_pledges SET status=?,updated_at=NOW() WHERE id=?')->execute([$newStatus,$pledgeId]);if($action==='receive'){update_wardrobe_reservations($pdo,$pledgeId,'donated');$complete=$pdo->prepare("SELECT COUNT(*) FROM request_requirements rr WHERE rr.request_id=? AND rr.quantity_needed > COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id WHERE di.request_requirement_id=rr.id AND dp.status='received'),0)");$complete->execute([$pledge['request_id']]);if(!(int)$complete->fetchColumn())$pdo->prepare("UPDATE clothing_requests SET status='fulfilled' WHERE id=?")->execute([$pledge['request_id']]);$impact=complete_donation_impact($pdo,$pledgeId);}if($action==='cancel')update_wardrobe_reservations($pdo,$pledgeId,'released');if($action==='approve')create_notification($pdo,(int)$pledge['donor_id'],'pledge','Your pledge was approved','Great news—your pledge is approved. Pick a drop-off time when you are ready.','donor/appointment.php?pledge='.$pledgeId);if($action==='cancel')create_notification($pdo,(int)$pledge['donor_id'],'pledge','Pledge update','This pledge was not able to be accepted. Please browse other current needs.','donor/browse.php');$message=$action==='approve'?'Pledge approved. The donor can now book their drop-off.':($action==='receive'?'Donation received—your request totals are updated and donor impact was awarded.':'Pledge cancelled.');log_activity($pdo,$action==='receive'?'received a donation':($action==='approve'?'approved a donation pledge':'cancelled a donation pledge'),(int)$user['id'],'pledge',$pledgeId);$pdo->commit();flash('success',$message);}catch(Throwable $e){$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'We could not update that pledge.');}redirect('charity/donations.php');}
$status=$_GET['status']??'';$where='cr.charity_id=?';$params=[$charityId];if(in_array($status,['pending','approved','scheduled','received','cancelled'],true)){$where.=' AND dp.status=?';$params[]=$status;}$stmt=$pdo->prepare("SELECT dp.*,u.name donor_name,u.email donor_email,cr.title,cr.collection_location,a.appointment_date,a.time_slot,COALESCE(SUM(di.quantity),0) quantity,(SELECT GROUP_CONCAT(DISTINCT CONCAT(wi.name,' (',wi.condition_label,')') ORDER BY wi.name SEPARATOR ', ') FROM wardrobe_reservations wr JOIN wardrobe_items wi ON wi.id=wr.wardrobe_item_id WHERE wr.pledge_id=dp.id AND wr.status IN ('reserved','donated')) wardrobe_items FROM donation_pledges dp JOIN users u ON u.id=dp.donor_id JOIN clothing_requests cr ON cr.id=dp.request_id LEFT JOIN donation_items di ON di.pledge_id=dp.id LEFT JOIN appointments a ON a.pledge_id=dp.id AND a.status='booked' WHERE $where GROUP BY dp.id ORDER BY FIELD(dp.status,'pending','scheduled','approved','received','cancelled'),dp.created_at DESC");$stmt->execute($params);$pledges=$stmt->fetchAll();$pageTitle='Manage donations';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">Pledges becoming impact</span><h1>Donation inbox</h1><p>Approve what fits your need, then confirm only items you actually receive.</p></div><a class="button button-outline" href="<?=e(url('charity/appointments.php'))?>">View appointments</a></div><div class="filter-card" style="margin:0 0 20px"><div class="request-meta"><a class="chip <?=!$status?'chip-sun':''?>" href="<?=e(url('charity/donations.php'))?>">All</a><?php foreach(['pending','approved','scheduled','received','cancelled'] as $s):?><a class="chip <?=$status===$s?'chip-sun':''?>" href="<?=e(url('charity/donations.php?status='.$s))?>"><?=e(ucfirst($s))?></a><?php endforeach;?></div></div><div class="panel"><?php if(!$pledges):?><div class="empty"><span class="empty-icon">✦</span>No donations in this view.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Donor & request</th><th>Items</th><th>Appointment</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($pledges as $p):?><tr><td><strong><?=e($p['donor_name'])?></strong><br><span class="muted"><?=e($p['title'])?></span><?php if($p['wardrobe_items']):?><br><small class="muted">Wardrobe: <?=e($p['wardrobe_items'])?></small><?php endif;?><?php if($p['donor_notes']):?><br><small class="muted">“<?=e($p['donor_notes'])?>”</small><?php endif;?></td><td><?=$p['quantity']?></td><td><?php if($p['appointment_date']):?><?=format_date($p['appointment_date'],'d M')?><br><?=e(substr($p['time_slot'],0,5))?><?php else:?><span class="muted">Not booked</span><?php endif;?></td><td><span class="status <?=e(status_class($p['status']))?>"><?=e($p['status'])?></span></td><td class="row-actions"><?php if($p['status']==='pending'):?><form method="post" data-loading><?=csrf_field()?><input type="hidden" name="pledge_id" value="<?=$p['id']?>"><input type="hidden" name="action" value="approve"><button class="button button-small">Approve</button></form><?php endif;?><?php if(in_array($p['status'],['approved','scheduled'],true)):?><form method="post" data-loading data-confirm="Mark these items as received? This updates totals permanently."><?=csrf_field()?><input type="hidden" name="pledge_id" value="<?=$p['id']?>"><input type="hidden" name="action" value="receive"><button class="button button-small button-sun">Receive</button></form><?php endif;?><?php if(in_array($p['status'],['pending','approved','scheduled'],true)):?><form method="post" data-loading data-confirm="Cancel this pledge?"><?=csrf_field()?><input type="hidden" name="pledge_id" value="<?=$p['id']?>"><input type="hidden" name="action" value="cancel"><button class="button button-danger button-small">Decline</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
